INSERT INTO it_glossary (term_ja, reading, term_ko, term_en, category, description, example_sentence) VALUES
  ('TCP/IP', 'ティーシーピーアイピー', 'TCP/IP', 'TCP/IP', 'infrastructure', '인터넷에서 데이터를 주고받기 위한 기본 통신 규약(프로토콜)의 집합입니다.', 'TCP/IPの基礎知識はネットワークエンジニアにとって必須です。'),
  ('LAN', 'ラン', 'LAN', 'Local Area Network', 'infrastructure', '같은 건물이나 사무실 등 좁은 범위에서 컴퓨터를 연결하는 네트워크입니다.', '社内LANに接続してファイルサーバーにアクセスしてください。'),
  ('WAN', 'ワン', 'WAN', 'Wide Area Network', 'infrastructure', '본사와 지사 등 멀리 떨어진 장소를 연결하는 넓은 범위의 네트워크입니다.', 'WANを利用して本社と支社のネットワークを接続しています。'),
  ('ルーター', 'ルーター', '라우터', 'Router', 'infrastructure', '네트워크 간에 데이터를 최적의 경로로 전달하는 장치입니다.', 'ルーターの設定を変更してネットワークのセグメントを分割します。'),
  ('スイッチ', 'スイッチ', '스위치', 'Switch', 'infrastructure', '같은 네트워크 내에서 데이터를 목적지 장치로 정확히 전달하는 장치입니다.', 'スイッチのポートにケーブルを接続してネットワークを構成します。'),
  ('ハブ', 'ハブ', '허브', 'Hub', 'infrastructure', '여러 대의 컴퓨터를 연결하여 네트워크를 구성하는 단순한 집선 장치입니다.', 'ハブを使って複数のPCをネットワークに接続しました。'),
  ('プロトコル', 'プロトコル', '프로토콜', 'Protocol', 'infrastructure', '컴퓨터 간에 데이터를 주고받기 위해 정해진 통신 규약입니다.', '通信プロトコルを確認してからシステム連携を設計してください。'),
  ('HTTP/HTTPS', 'エイチティーティーピーエイチティーティーピーエス', 'HTTP/HTTPS', 'HTTP/HTTPS', 'infrastructure', '웹 브라우저와 웹 서버 사이에서 데이터를 주고받는 프로토콜입니다. HTTPS는 암호화가 추가된 버전입니다.', 'セキュリティのためHTTPSでの通信を必須にしています。'),
  ('FTP', 'エフティーピー', 'FTP', 'File Transfer Protocol', 'infrastructure', '네트워크를 통해 파일을 전송하기 위한 프로토콜입니다.', 'FTPサーバーにファイルをアップロードしてください。'),
  ('SMTP', 'エスエムティーピー', 'SMTP', 'Simple Mail Transfer Protocol', 'infrastructure', '이메일을 보내기 위해 사용하는 통신 프로토콜입니다.', 'SMTPサーバーの設定を確認してメール送信のテストを行います。'),
  ('POP3', 'ポップスリー', 'POP3', 'Post Office Protocol 3', 'infrastructure', '메일 서버에서 이메일을 수신하여 로컬에 다운로드하는 프로토콜입니다.', 'POP3でメールを受信する設定にしています。'),
  ('IMAP', 'アイマップ', 'IMAP', 'Internet Message Access Protocol', 'infrastructure', '메일 서버에 이메일을 보관한 채 열람하는 프로토콜입니다. 여러 기기에서 동기화가 가능합니다.', 'IMAPを使えば複数のデバイスでメールを同期できます。'),
  ('DHCP', 'ディーエイチシーピー', 'DHCP', 'Dynamic Host Configuration Protocol', 'infrastructure', '네트워크에 접속하는 장치에 자동으로 IP 주소를 할당하는 프로토콜입니다.', 'DHCPサーバーが自動的にIPアドレスを割り当てています。'),
  ('サブネットマスク', 'サブネットマスク', '서브넷 마스크', 'Subnet Mask', 'infrastructure', 'IP 주소에서 네트워크 부분과 호스트 부분을 구분하기 위한 값입니다.', 'サブネットマスクを255.255.255.0に設定してください。'),
  ('MACアドレス', 'マックアドレス', 'MAC 주소', 'MAC Address', 'infrastructure', '네트워크 장치에 부여된 고유한 물리적 주소입니다. 세계에서 유일한 값을 가집니다.', '機器のMACアドレスを確認してアクセス制御リストに追加してください。'),
  ('ゲートウェイ', 'ゲートウェイ', '게이트웨이', 'Gateway', 'infrastructure', '서로 다른 네트워크를 연결하는 출입구 역할을 하는 장치입니다.', 'デフォルトゲートウェイの設定を確認してください。'),
  ('NAT', 'ナット', 'NAT', 'Network Address Translation', 'infrastructure', '사설 IP 주소와 공인 IP 주소를 상호 변환하는 기술입니다. 사내 네트워크에서 인터넷 접속에 사용됩니다.', 'NATを使ってプライベートIPアドレスをグローバルIPに変換しています。'),
  ('帯域幅', 'たいいきはば', '대역폭', 'Bandwidth', 'infrastructure', '네트워크를 통해 일정 시간 동안 전송할 수 있는 데이터의 최대 양입니다.', '帯域幅が不足しているため、動画配信が遅延しています。'),
  ('パケット', 'パケット', '패킷', 'Packet', 'infrastructure', '네트워크에서 데이터를 전송할 때 작은 단위로 분할한 데이터 묶음입니다.', 'パケットの損失率を確認してネットワーク品質を評価します。'),
  ('ドメイン名', 'ドメインめい', '도메인명', 'Domain Name', 'infrastructure', '숫자로 된 IP 주소를 사람이 이해하기 쉬운 이름으로 표현한 것입니다. 예: example.com', '新しいドメイン名を取得してWebサイトを公開します。'),
  ('URL', 'ユーアールエル', 'URL', 'Uniform Resource Locator', 'infrastructure', '인터넷에서 특정 자원(웹페이지 등)의 위치를 나타내는 주소입니다.', 'APIのURLを確認してからリクエストを送信してください。'),
  ('Wi-Fi', 'ワイファイ', 'Wi-Fi', 'Wi-Fi', 'infrastructure', '무선으로 인터넷에 접속할 수 있게 하는 기술입니다.', '会議室のWi-Fiに接続してオンラインミーティングに参加してください。'),
  ('Bluetooth', 'ブルートゥース', '블루투스', 'Bluetooth', 'infrastructure', '짧은 거리에서 기기 간에 데이터를 무선으로 주고받는 통신 기술입니다.', 'Bluetoothでキーボードとマウスをパソコンに接続しています。'),
  ('IoT', 'アイオーティー', 'IoT', 'Internet of Things', 'infrastructure', '가전제품, 센서 등 다양한 사물이 인터넷에 연결되어 데이터를 주고받는 개념입니다.', 'IoTデバイスのセキュリティ対策が重要な課題になっています。'),
  ('クラウドコンピューティング', 'クラウドコンピューティング', '클라우드 컴퓨팅', 'Cloud Computing', 'infrastructure', '인터넷을 통해 서버, 스토리지, 소프트웨어 등의 IT 자원을 필요한 만큼 이용하는 방식입니다.', 'クラウドコンピューティングを活用してインフラコストを削減しました。'),
  ('仮想化', 'かそうか', '가상화', 'Virtualization', 'infrastructure', '하나의 물리적 장비 위에 여러 개의 가상 환경을 만드는 기술입니다.', '仮想化技術を使ってサーバーの利用効率を向上させています。'),
  ('VoIP', 'ブイオーアイピー', 'VoIP', 'Voice over IP', 'infrastructure', '인터넷을 이용하여 음성 통화를 하는 기술입니다. IP 전화라고도 합니다.', 'VoIPを導入して通話コストを大幅に削減しました。'),
  ('トポロジー', 'トポロジー', '토폴로지', 'Topology', 'infrastructure', '네트워크의 물리적 또는 논리적 연결 형태를 나타내는 구조입니다.', 'ネットワークトポロジーを確認してから障害箇所を特定します。'),
  ('QoS', 'キューオーエス', 'QoS', 'Quality of Service', 'infrastructure', '네트워크에서 특정 통신에 대해 우선순위를 부여하여 품질을 보장하는 기술입니다.', 'QoSを設定して音声通話の優先度を上げました。'),
  ('5G', 'ファイブジー', '5G', '5G', 'infrastructure', '제5세대 이동 통신 시스템으로, 초고속, 초저지연, 대량 접속이 특징입니다.', '5G通信によりリアルタイムの遠隔操作が可能になりました。')
